const items = $input.all();
return items.map(item => {
  const payload = item.json.body || item.json;
  const issue = payload.issue || payload;
  const action = payload.action || 'opened';

  // Map GitHub labels to priority
  const labels = (issue.labels || []).map(l => l.name || l);
  let priority = 'Medium';
  if (labels.some(l => l.toLowerCase().includes('critical') || l.toLowerCase().includes('p0'))) priority = 'Critical';
  else if (labels.some(l => l.toLowerCase().includes('high') || l.toLowerCase().includes('p1'))) priority = 'High';
  else if (labels.some(l => l.toLowerCase().includes('low') || l.toLowerCase().includes('p3'))) priority = 'Low';

  return {
    json: {
      action,
      title: issue.title || 'Untitled Issue',
      body: (issue.body || '').substring(0, 2000),
      issueNumber: issue.number || 0,
      url: issue.html_url || '',
      author: issue.user?.login || 'unknown',
      labels: labels.join(', '),
      priority,
      repo: payload.repository?.full_name || '',
      createdAt: issue.created_at || new Date().toISOString()
    }
  };
});

